args.content:
// argparse.mjs — minimal port of Python's argparse for the test13 CLI:
// one required option '--a' (type str, metavar 'A') plus the implicit -h/--help.
//
// Mimics Python 3.12 argparse semantics observed from the reference binary:
//   * '--a VALUE' and '--a=VALUE'
//   * last duplicate wins
//   * allow_abbrev=True long-option matching ('--h', '--he', ... -> '--help')
//   * tokens starting with '-' are option strings EXCEPT:
//       - the single char '-'
//       - negative-number-like tokens (argparse's ^-\d+$ | ^-\d*\.\d+$)
//       - tokens containing a space
//   * '--' : the token itself and everything after it are treated as
//     positionals; with no positionals defined they all land in "extras"
//     (CPython 3.12 only strips '--' from values consumed by a positional,
//     so here it shows up in the unrecognized-arguments list).
//   * error precedence: while parsing, the first failing option errors
//     immediately; after parsing, a missing required '--a' errors BEFORE
//     the unrecognized-arguments check.
//   * all usage errors: usage + error on stderr, exit code 2
//   * -h/--help: help text on stdout, exit code 0 (fires the moment the
//     option is consumed, even if other errors would occur later)

const OPTION_STRINGS = ['-h', '--help', '--a'];

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function allDigits(s) {
  if (s.length === 0) return false;
  for (let i = 0; i < s.length; i++) {
    if (!isDigit(s[i])) return false;
  }
  return true;
}

// argparse._negative_number_matcher = ^-\d+$ | ^-\d*\.\d+$
function isNegativeNumberLike(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  const rest = s.slice(1);
  if (allDigits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot < 0) return false;
  if (rest.indexOf('.', dot + 1) >= 0) return false;
  const intPart = rest.slice(0, dot);
  const fracPart = rest.slice(dot + 1);
  if (intPart.length > 0 && !allDigits(intPart)) return false;
  return allDigits(fracPart);
}

function containsChar(s, ch) {
  return s.indexOf(ch) >= 0;
}

function startsWith(s, prefix) {
  return s.slice(0, prefix.length) === prefix;
}

// Port of argparse._get_option_tuples: abbreviation matches.
// Returns array of { optionString, explicitArg } (explicitArg null if none).
function getOptionTuples(token) {
  const result = [];
  if (token.length >= 2 && token[0] === '-' && token[1] === '-') {
    // long option: prefix match, optional '=value'
    let optionPrefix = token;
    let explicitArg = null;
    const eq = token.indexOf('=');
    if (eq >= 0) {
      optionPrefix = token.slice(0, eq);
      explicitArg = token.slice(eq + 1);
    }
    for (const opt of OPTION_STRINGS) {
      if (startsWith(opt, optionPrefix)) {
        result.push({ optionString: opt, explicitArg });
      }
    }
  } else if (token.length >= 2 && token[0] === '-' && token[1] !== '-') {
    // short option: '-h<rest>' concatenation, or prefix of a longer name
    let optionPrefix = token;
    let explicitArg = null;
    const eq = token.indexOf('=');
    if (eq >= 0) {
      optionPrefix = token.slice(0, eq);
      explicitArg = token.slice(eq + 1);
    }
    const shortOptionPrefix = token.slice(0, 2);
    const shortExplicitArg = token.slice(2);
    for (const opt of OPTION_STRINGS) {
      if (opt === shortOptionPrefix) {
        result.push({ optionString: opt, explicitArg: shortExplicitArg });
      } else if (startsWith(opt, optionPrefix)) {
        result.push({ optionString: opt, explicitArg });
      }
    }
  }
  return result;
}

// Port of argparse._parse_optional.
// Returns null when the token is a plain value ('A' pattern), otherwise
// { kind: 'help' | 'a' | 'unknown', optionString, explicitArg }.
// Throws { ambiguous: matches } conceptually via kind 'ambiguous'.
function parseOptional(token) {
  // doesn't start with a prefix char -> value
  if (token.length === 0 || token[0] !== '-') return null;

  // exact option string
  if (OPTION_STRINGS.indexOf(token) >= 0) {
    return { kind: actionKind(token), optionString: token, explicitArg: null };
  }

  // single character '-' -> value
  if (token.length === 1) return null;

  // 'option=value' with an exact option name
  const eq = token.indexOf('=');
  if (eq >= 0) {
    const head = token.slice(0, eq);
    if (OPTION_STRINGS.indexOf(head) >= 0) {
      return { kind: actionKind(head), optionString: head, explicitArg: token.slice(eq + 1) };
    }
  }

  // abbreviation search
  const tuples = getOptionTuples(token);
  if (tuples.length > 1) {
    const matches = tuples.map((t) => t.optionString);
    return { kind: 'ambiguous', optionString: token, explicitArg: null, matches };
  } else if (tuples.length === 1) {
    const t = tuples[0];
    return { kind: actionKind(t.optionString), optionString: t.optionString, explicitArg: t.explicitArg };
  }

  // negative-number-like -> value (no option looks like a negative number)
  if (isNegativeNumberLike(token)) return null;

  // contains a space -> value
  if (containsChar(token, ' ')) return null;

  // starts with '-' but matches nothing -> unknown optional
  return { kind: 'unknown', optionString: token, explicitArg: null };
}

function actionKind(optionString) {
  return optionString === '--a' ? 'a' : 'help';
}

export function parseArgs(argv, prog) {
  const usage = 'usage: ' + prog + ' [-h] --a A\n';

  const fail = (message) => {
    process.stderr.write(usage);
    process.stderr.write(prog + ': error: ' + message + '\n');
    process.exit(2);
  };

  const printHelp = () => {
    process.stdout.write(usage);
    process.stdout.write('\n');
    process.stdout.write('options:\n');
    process.stdout.write('  -h, --help  show this help message and exit\n');
    process.stdout.write('  --a A\n');
    process.exit(0);
  };

  const extras = [];
  let aValue = null;
  let seenA = false;

  // Everything from the first '--' onward is non-option (positional).
  let doubleDashIndex = -1;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--') {
      doubleDashIndex = i;
      break;
    }
  }
  const optionEnd = doubleDashIndex >= 0 ? doubleDashIndex : argv.length;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    if (i >= optionEnd) {
      // '--' itself and everything after it: positionals -> extras
      extras.push(token);
      i++;
      continue;
    }
    const opt = parseOptional(token);
    if (opt === null) {
      // positional value; no positionals are defined -> extra
      extras.push(token);
      i++;
      continue;
    }
    if (opt.kind === 'ambiguous') {
      fail('ambiguous option: ' + token + ' could match ' + opt.matches.join(', '));
    }
    if (opt.kind === 'unknown') {
      extras.push(token);
      i++;
      continue;
    }
    if (opt.kind === 'help') {
      if (opt.explicitArg !== null && opt.explicitArg !== undefined) {
        if (opt.optionString === '-h') {
          // short form '-hX': the zero-arg action fires, X is never reached
          printHelp();
        }
        fail("argument -h/--help: ignored explicit argument '" + opt.explicitArg + "'");
      }
      printHelp();
    }
    // opt.kind === 'a'
    let value;
    if (opt.explicitArg !== null && opt.explicitArg !== undefined) {
      value = opt.explicitArg;
      i++;
    } else {
      const next = i + 1 < optionEnd ? argv[i + 1] : undefined;
      if (next !== undefined && parseOptional(next) === null) {
        value = next;
        i += 2;
      } else {
        fail('argument --a: expected one argument');
      }
    }
    aValue = value;
    seenA = true;
  }

  if (!seenA) {
    fail('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail('unrecognized arguments: ' + extras.join(' '));
  }

  return { a: aValue };
}

export default parseArgs;

