// resolve.mjs — PyYAML (SafeLoader/SafeDumper) scalar resolution and formatting helpers.
// Pure ESM, zero dependencies, no JSON, no regular expressions.
//
// Data model ("nodes"):
//   { kind: 'str', value: string }
//   { kind: 'int', value: BigInt }
//   { kind: 'float', value: number }               // may be Infinity / -Infinity / NaN
//   { kind: 'bool', value: boolean }
//   { kind: 'null' }
//   { kind: 'ts', dateOnly, year, month, day, hour, minute, second, microsecond, offsetMin }
//   { kind: 'binary', value: Uint8Array }
//   { kind: 'seq', items: Node[] }
//   { kind: 'map' | 'set', entries: Array<[keyNode, valueNode]> }

// ---------------------------------------------------------------------------
// small helpers (manual character scanning — no regex allowed)

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isHexDigit(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

function hexDigitValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  return ch.charCodeAt(0) - 55; // 'A'-'F'
}

function stripUnderscores(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== '_') out += s[i];
  }
  return out;
}

function padLeft(n, width) {
  let s = String(n);
  while (s.length < width) s = '0' + s;
  return s;
}

// ---------------------------------------------------------------------------
// plain scalar resolution (PyYAML SafeLoader implicit resolvers, YAML 1.1)

const BOOL_TRUE = ['yes', 'Yes', 'YES', 'true', 'True', 'TRUE', 'on', 'On', 'ON'];
const BOOL_FALSE = ['no', 'No', 'NO', 'false', 'False', 'FALSE', 'off', 'Off', 'OFF'];

function matchBool(text) {
  for (let i = 0; i < BOOL_TRUE.length; i++) {
    if (text === BOOL_TRUE[i]) return true;
  }
  for (let i = 0; i < BOOL_FALSE.length; i++) {
    if (text === BOOL_FALSE[i]) return false;
  }
  return undefined;
}

function matchNull(text) {
  return text === '' || text === '~' || text === 'null' || text === 'Null' || text === 'NULL';
}

// Match one sexagesimal group "[0-5]?[0-9]" starting at index p.
// Returns group length (1 or 2), or 0 when there is no valid group.
function matchSexaGroup(text, p) {
  const d1 = text[p];
  const d2 = text[p + 1];
  if (d1 !== undefined && isDigit(d1)) {
    if (d2 !== undefined && isDigit(d2) && d1 <= '5') return 2;
    return 1;
  }
  return 0;
}

// Scan a run of [0-9_] starting at p; returns end index.
function scanDigitsUnderscores(text, p) {
  const n = text.length;
  while (p < n && (isDigit(text[p]) || text[p] === '_')) p++;
  return p;
}

// Match exponent part "(?:[eE][-+][0-9]+)?" starting at p.
// Returns end index when valid (p itself when no exponent present), or -1 when
// an 'e'/'E' is present but malformed.
function matchExponent(text, p) {
  const n = text.length;
  const ch = text[p];
  if (ch !== 'e' && ch !== 'E') return p;
  p++;
  const s = text[p];
  if (s !== '+' && s !== '-') return -1;
  p++;
  const start = p;
  while (p < n && isDigit(text[p])) p++;
  if (p === start) return -1;
  return p;
}

// PyYAML float resolver regex (YAML 1.1):
//   [-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?
//   | \.[0-9_]+(?:[eE][-+][0-9]+)?
//   | [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
//   | [-+]?\.(?:inf|Inf|INF)
//   | \.(?:nan|NaN|NAN)
// Returns the numeric value, or undefined when text is not a float.
function matchFloat(text) {
  const n = text.length;
  let i = 0;
  let sign = 1;
  if (text[i] === '-') { sign = -1; i++; } else if (text[i] === '+') { i++; }
  const body = text.slice(i);

  if (body === '.inf' || body === '.Inf' || body === '.INF') return sign * Infinity;
  // signed nan is NOT a float (stays a plain string)
  if (i === 0 && (body === '.nan' || body === '.NaN' || body === '.NAN')) return NaN;

  if (i < n && isDigit(text[i])) {
    const k = scanDigitsUnderscores(text, i); // first digit group: [0-9][0-9_]*
    if (text[k] === ':') {
      // sexagesimal float: first(?::[0-5]?[0-9])+\.[0-9_]*
      let p = k;
      const groups = [stripUnderscores(text.slice(i, k))];
      while (text[p] === ':') {
        p++;
        const glen = matchSexaGroup(text, p);
        if (glen === 0) return undefined;
        groups.push(text.substr(p, glen));
        p += glen;
      }
      if (text[p] !== '.') return undefined; // could still be a sexagesimal int
      p++;
      const fend = scanDigitsUnderscores(text, p);
      if (fend !== n) return undefined;
      const fracPart = stripUnderscores(text.slice(p, fend));
      // last group carries the fraction; combine in base 60 like PyYAML does
      let value = 0;
      for (let g = groups.length - 1; g >= 0; g--) {
        let part = groups[g];
        if (g === groups.length - 1) part = part + '.' + (fracPart === '' ? '0' : fracPart);
        value = value * 60 + Number(part);
      }
      return sign * value;
    }
    if (text[k] === '.') {
      // [0-9][0-9_]*\.[0-9_]*(?:exp)?
      const p = scanDigitsUnderscores(text, k + 1);
      const e = matchExponent(text, p);
      if (e < 0 || e !== n) return undefined;
      return Number(stripUnderscores(text.slice(0, k)) + '.' + stripUnderscores(text.slice(k + 1, p)) + text.slice(p, e)) * 1;
    }
    return undefined;
  }

  if (text[i] === '.') {
    // \.[0-9_]+(?:exp)?
    const start = i + 1;
    const p = scanDigitsUnderscores(text, start);
    if (p === start) return undefined;
    const e = matchExponent(text, p);
    if (e < 0 || e !== n) return undefined;
    const cleaned = (sign < 0 ? '-' : '') + '.' + stripUnderscores(text.slice(start, p)) + text.slice(p, e);
    return Number(cleaned);
  }

  return undefined;
}

// PyYAML int resolver regex (YAML 1.1):
//   [-+]?0b[0-1_]+
//   | [-+]?0[0-7_]+
//   | [-+]?(?:0|[1-9][0-9_]*)
//   | [-+]?0x[0-9a-fA-F_]+
//   | [-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+
// Returns the BigInt value, or undefined when text is not an int.
function matchInt(text) {
  const n = text.length;
  let i = 0;
  let neg = false;
  if (text[i] === '-') { neg = true; i++; } else if (text[i] === '+') { i++; }
  if (i >= n) return undefined;

  // binary: 0b[0-1_]+
  if (text[i] === '0' && text[i + 1] === 'b') {
    let p = i + 2;
    const start = p;
    let value = 0n;
    while (p < n && (text[p] === '0' || text[p] === '1' || text[p] === '_')) {
      if (text[p] !== '_') value = value * 2n + BigInt(text[p].charCodeAt(0) - 48);
      p++;
    }
    if (p === start || p !== n) return undefined;
    return neg ? -value : value;
  }

  // hex: 0x[0-9a-fA-F_]+
  if (text[i] === '0' && text[i + 1] === 'x') {
    let p = i + 2;
    const start = p;
    let value = 0n;
    while (p < n && (isHexDigit(text[p]) || text[p] === '_')) {
      if (text[p] !== '_') value = value * 16n + BigInt(hexDigitValue(text[p]));
      p++;
    }
    if (p === start || p !== n) return undefined;
    return neg ? -value : value;
  }

  if (text[i] === '0') {
    // '0' alone (decimal), or octal 0[0-7_]+
    if (i + 1 === n) return 0n;
    let p = i + 1;
    let value = 0n;
    while (p < n && ((text[p] >= '0' && text[p] <= '7') || text[p] === '_')) {
      if (text[p] !== '_') value = value * 8n + BigInt(text[p].charCodeAt(0) - 48);
      p++;
    }
    if (p !== n) return undefined; // e.g. '08' -> string
    return neg ? -value : value;
  }

  if (text[i] >= '1' && text[i] <= '9') {
    const k = scanDigitsUnderscores(text, i); // [1-9][0-9_]*
    if (k === n) {
      // plain decimal
      const value = BigInt(stripUnderscores(text.slice(i, k)));
      return neg ? -value : value;
    }
    if (text[k] === ':') {
      // sexagesimal: [1-9][0-9_]*(?::[0-5]?[0-9])+
      let value = BigInt(stripUnderscores(text.slice(i, k)));
      let p = k;
      while (text[p] === ':') {
        p++;
        const glen = matchSexaGroup(text, p);
        if (glen === 0) return undefined;
        value = value * 60n + BigInt(text.substr(p, glen));
        p += glen;
      }
      if (p !== n) return undefined;
      return neg ? -value : value;
    }
    return undefined;
  }

  return undefined;
}

// Error matching Python's ValueError raised by datetime/date construction.
// `pyLine` records the line of yaml/constructor.py the CPython traceback shows
// (330 for date(), 347 for the tz check, 350 for datetime()) so the CLI layer
// can reproduce PyYAML's uncaught-ValueError traceback text.
function timestampError(message, pyLine) {
  const err = new Error(message);
  err.name = 'ValueError';
  err.pyLine = pyLine;
  return err;
}

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y, m) {
  switch (m) {
    case 1: case 3: case 5: case 7: case 8: case 10: case 12: return 31;
    case 4: case 6: case 9: case 11: return 30;
    default: return isLeapYear(y) ? 29 : 28;
  }
}

// Python repr() of a timedelta whole minutes value (used in the tz error text).
function timedeltaRepr(totalMinutes) {
  const totalSeconds = totalMinutes * 60;
  const days = Math.floor(totalSeconds / 86400);
  const seconds = totalSeconds - days * 86400;
  if (seconds === 0) return 'datetime.timedelta(days=' + days + ')';
  if (days === 0) return 'datetime.timedelta(seconds=' + seconds + ')';
  return 'datetime.timedelta(days=' + days + ', seconds=' + seconds + ')';
}

// PyYAML timestamp resolver regex (YAML 1.1):
//   [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]                 (date only)
//   | [0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?
//     (?:[Tt]|[ \t]+)[0-9][0-9]?:[0-9][0-9]:[0-9][0-9]
//     (?:\.[0-9]*)?
//     (?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-9][0-9])?))?
// Returns a ts node, or undefined when text does not match. Throws
// (ValueError-like) on out-of-range calendar/clock/offset values, like PyYAML.
function matchTimestamp(text) {
  const n = text.length;
  let i = 0;

  // year: exactly 4 digits
  if (n < 4) return undefined;
  for (let k = 0; k < 4; k++) {
    if (!isDigit(text[k])) return undefined;
  }
  const year = Number(text.slice(0, 4));
  i = 4;
  if (text[i] !== '-') return undefined;
  i++;

  // month: 1-2 digits
  const mStart = i;
  while (i < n && isDigit(text[i]) && i - mStart < 2) i++;
  const mLen = i - mStart;
  if (mLen === 0) return undefined;
  const month = Number(text.slice(mStart, i));
  if (text[i] !== '-') return undefined;
  i++;

  // day: 1-2 digits
  const dStart = i;
  while (i < n && isDigit(text[i]) && i - dStart < 2) i++;
  const dLen = i - dStart;
  if (dLen === 0) return undefined;
  const day = Number(text.slice(dStart, i));

  const validateDate = (pyLine) => {
    if (year < 1) throw timestampError('year ' + year + ' is out of range', pyLine);
    if (month < 1 || month > 12) throw timestampError('month must be in 1..12', pyLine);
    if (day < 1 || day > daysInMonth(year, month)) {
      throw timestampError('day is out of range for month', pyLine);
    }
  };

  if (i === n) {
    // date-only form requires exactly 2-digit month and day
    if (mLen !== 2 || dLen !== 2) return undefined;
    validateDate(330);
    return {
      kind: 'ts', dateOnly: true,
      year, month, day,
      hour: 0, minute: 0, second: 0, microsecond: 0,
      offsetMin: null,
    };
  }

  // separator: [Tt] or [ \t]+
  const sep = text[i];
  if (sep === 'T' || sep === 't') {
    i++;
  } else if (sep === ' ' || sep === '\t') {
    while (text[i] === ' ' || text[i] === '\t') i++;
  } else {
    return undefined;
  }

  // hour: 1-2 digits
  const hStart = i;
  while (i < n && isDigit(text[i]) && i - hStart < 2) i++;
  if (i === hStart) return undefined;
  const hour = Number(text.slice(hStart, i));
  if (text[i] !== ':') return undefined;
  i++;

  // minute: exactly 2 digits
  if (!(i + 1 < n && isDigit(text[i]) && isDigit(text[i + 1]))) return undefined;
  const minute = Number(text.slice(i, i + 2));
  i += 2;
  if (text[i] !== ':') return undefined;
  i++;

  // second: exactly 2 digits
  if (!(i + 1 < n && isDigit(text[i]) && isDigit(text[i + 1]))) return undefined;
  const second = Number(text.slice(i, i + 2));
  i += 2;

  // fraction: (?:\.[0-9]*)?
  let microsecond = 0;
  if (text[i] === '.') {
    i++;
    const fStart = i;
    while (i < n && isDigit(text[i])) i++;
    let frac = text.slice(fStart, i);
    if (frac.length > 6) frac = frac.slice(0, 6); // truncated, not rounded
    while (frac.length < 6) frac += '0';
    microsecond = Number(frac);
  }

  // timezone: [ \t]* (Z | [-+][0-9][0-9]?(?::[0-9][0-9])?)?
  while (text[i] === ' ' || text[i] === '\t') i++;
  let offsetMin = null;
  if (i < n) {
    const tz = text[i];
    if (tz === 'Z') {
      i++;
      offsetMin = 0;
    } else if (tz === '+' || tz === '-') {
      i++;
      const tStart = i;
      while (i < n && isDigit(text[i]) && i - tStart < 2) i++;
      if (i === tStart) return undefined;
      const tzHour = Number(text.slice(tStart, i));
      let tzMinute = 0;
      if (text[i] === ':') {
        i++;
        if (!(i + 1 < n && isDigit(text[i]) && isDigit(text[i + 1]))) return undefined;
        tzMinute = Number(text.slice(i, i + 2));
        i += 2;
      }
      let delta = tzHour * 60 + tzMinute;
      if (tz === '-') delta = -delta;
      if (delta >= 1440 || delta <= -1440) {
        throw timestampError(
          'offset must be a timedelta strictly between -timedelta(hours=24) ' +
          'and timedelta(hours=24), not ' + timedeltaRepr(delta) + '.',
          347);
      }
      offsetMin = delta;
    } else {
      return undefined;
    }
  }
  if (i !== n) return undefined;

  if (hour > 23) throw timestampError('hour must be in 0..23', 350);
  if (minute > 59) throw timestampError('minute must be in 0..59', 350);
  if (second > 59) throw timestampError('second must be in 0..59', 350);
  validateDate(350);

  return {
    kind: 'ts', dateOnly: false,
    year, month, day, hour, minute, second, microsecond,
    offsetMin,
  };
}

// Full plain-scalar resolution. Returns a scalar node. Anything that does not
// match a YAML 1.1 implicit type becomes a plain str node.
export function resolvePlainScalar(text) {
  const b = matchBool(text);
  if (b !== undefined) return { kind: 'bool', value: b };
  if (matchNull(text)) return { kind: 'null' };
  const f = matchFloat(text);
  if (f !== undefined) return { kind: 'float', value: f };
  const iv = matchInt(text);
  if (iv !== undefined) return { kind: 'int', value: iv };
  const ts = matchTimestamp(text);
  if (ts !== undefined) return ts;
  return { kind: 'str', value: text };
}

export function makeStr(s) {
  return { kind: 'str', value: s };
}

// ---------------------------------------------------------------------------
// Python == semantics for mapping keys

function isNumericKind(kind) {
  return kind === 'int' || kind === 'float' || kind === 'bool';
}

// Numeric value of a numeric node as either BigInt (int, bool) or number (float).
function numericValue(node) {
  if (node.kind === 'bool') return node.value ? 1n : 0n;
  return node.value;
}

function numericEqual(av, bv) {
  const aBig = typeof av === 'bigint';
  const bBig = typeof bv === 'bigint';
  if (aBig && bBig) return av === bv;
  if (!aBig && !bBig) return av === bv; // NaN !== NaN, -0 === 0 — both correct
  const big = aBig ? av : bv;
  const num = aBig ? bv : av;
  if (!Number.isFinite(num)) return false;
  if (!Number.isInteger(num)) return false;
  return big === BigInt(num);
}

// Days-from-civil (Howard Hinnant) with BigInt, valid for years >= 1.
function daysFromCivil(year, month, day) {
  let y = BigInt(year);
  const m = BigInt(month);
  const d = BigInt(day);
  if (m <= 2n) y -= 1n;
  const era = y / 400n;
  const yoe = y - era * 400n;
  const mp = (m + 9n) % 12n;
  const doy = (153n * mp + 2n) / 5n + d - 1n;
  const doe = yoe * 365n + yoe / 4n - yoe / 100n + doy;
  return era * 146097n + doe;
}

// Absolute instant of an aware datetime node, in microseconds (BigInt).
function absoluteMicros(t) {
  let micros = daysFromCivil(t.year, t.month, t.day) * 86400n * 1000000n;
  micros += BigInt(t.hour) * 3600n * 1000000n;
  micros += BigInt(t.minute) * 60n * 1000000n;
  micros += BigInt(t.second) * 1000000n;
  micros += BigInt(t.microsecond);
  micros -= BigInt(t.offsetMin) * 60n * 1000000n;
  return micros;
}

function timestampEqual(a, b) {
  if (a.dateOnly !== b.dateOnly) return false;
  if (a.dateOnly) {
    return a.year === b.year && a.month === b.month && a.day === b.day;
  }
  const aAware = a.offsetMin !== null;
  const bAware = b.offsetMin !== null;
  if (aAware !== bAware) return false; // naive == aware is False in Python
  if (aAware) return absoluteMicros(a) === absoluteMicros(b);
  return a.year === b.year && a.month === b.month && a.day === b.day &&
    a.hour === b.hour && a.minute === b.minute && a.second === b.second &&
    a.microsecond === b.microsecond;
}

// Python == between two key nodes.
export function pythonKeyEqual(a, b) {
  if (isNumericKind(a.kind) && isNumericKind(b.kind)) {
    return numericEqual(numericValue(a), numericValue(b));
  }
  if (a.kind === 'str' && b.kind === 'str') return a.value === b.value;
  if (a.kind === 'null' && b.kind === 'null') return true;
  if (a.kind === 'ts' && b.kind === 'ts') return timestampEqual(a, b);
  if (a.kind === 'binary' && b.kind === 'binary') {
    const av = a.value;
    const bv = b.value;
    if (av.length !== bv.length) return false;
    for (let i = 0; i < av.length; i++) {
      if (av[i] !== bv[i]) return false;
    }
    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Python < ordering for sort_keys

// Exact comparison between a BigInt and a finite non-integer number.
function compareBigVsNonInteger(big, num) {
  // big < num  <=>  big <= floor(num)
  if (big <= BigInt(Math.floor(num))) return -1;
  return 1; // big >= ceil(num) > num
}

function compareNumericValues(av, bv) {
  const aBig = typeof av === 'bigint';
  const bBig = typeof bv === 'bigint';
  if (aBig && bBig) return av < bv ? -1 : (av > bv ? 1 : 0);
  if (!aBig && !bBig) {
    if (Number.isNaN(av) || Number.isNaN(bv)) return null;
    return av < bv ? -1 : (av > bv ? 1 : 0);
  }
  const big = aBig ? av : bv;
  const num = aBig ? bv : av;
  let cmp;
  if (Number.isNaN(num)) return null;
  if (num === Infinity) cmp = -1;
  else if (num === -Infinity) cmp = 1;
  else if (Number.isInteger(num)) cmp = big < BigInt(num) ? -1 : (big > BigInt(num) ? 1 : 0);
  else cmp = compareBigVsNonInteger(big, num);
  return aBig ? cmp : -cmp;
}

// Compare two strings by Unicode code point (not UTF-16 code unit).
function compareStringsCodePoint(a, b) {
  const ai = a[Symbol.iterator]();
  const bi = b[Symbol.iterator]();
  for (;;) {
    const an = ai.next();
    const bn = bi.next();
    if (an.done && bn.done) return 0;
    if (an.done) return -1;
    if (bn.done) return 1;
    const acp = an.value.codePointAt(0);
    const bcp = bn.value.codePointAt(0);
    if (acp !== bcp) return acp < bcp ? -1 : 1;
  }
}

function compareTimestamps(a, b) {
  if (a.dateOnly !== b.dateOnly) return null; // date vs datetime: TypeError
  if (a.dateOnly) {
    if (a.year !== b.year) return a.year < b.year ? -1 : 1;
    if (a.month !== b.month) return a.month < b.month ? -1 : 1;
    if (a.day !== b.day) return a.day < b.day ? -1 : 1;
    return 0;
  }
  const aAware = a.offsetMin !== null;
  const bAware = b.offsetMin !== null;
  if (aAware !== bAware) return null; // naive vs aware: TypeError
  if (aAware) {
    const am = absoluteMicros(a);
    const bm = absoluteMicros(b);
    return am < bm ? -1 : (am > bm ? 1 : 0);
  }
  const fields = ['year', 'month', 'day', 'hour', 'minute', 'second', 'microsecond'];
  for (let i = 0; i < fields.length; i++) {
    const f = fields[i];
    if (a[f] !== b[f]) return a[f] < b[f] ? -1 : 1;
  }
  return 0;
}

function compareBinary(a, b) {
  const av = a.value;
  const bv = b.value;
  const len = Math.min(av.length, bv.length);
  for (let i = 0; i < len; i++) {
    if (av[i] !== bv[i]) return av[i] < bv[i] ? -1 : 1;
  }
  if (av.length === bv.length) return 0;
  return av.length < bv.length ? -1 : 1;
}

// Python < total order between two key nodes. Returns -1/0/1, or null when the
// comparison would raise TypeError in Python (incomparable pair).
export function compareKeys(a, b) {
  if (a.kind === 'str' && b.kind === 'str') return compareStringsCodePoint(a.value, b.value);
  if (isNumericKind(a.kind) && isNumericKind(b.kind)) {
    return compareNumericValues(numericValue(a), numericValue(b));
  }
  if (a.kind === 'ts' && b.kind === 'ts') return compareTimestamps(a, b);
  if (a.kind === 'binary' && b.kind === 'binary') return compareBinary(a, b);
  return null; // includes null-vs-null (None < None raises TypeError)
}

// ---------------------------------------------------------------------------
// PyYAML float scalar text: '.inf' / '-.inf' / '.nan', else Python repr(x)
// lowercased with '.0' inserted before 'e' when the mantissa has no dot.

export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  const neg = x < 0;
  const ax = Math.abs(x);

  // Shortest round-trip digits from toExponential(): "d[.ddd]e±X".
  const es = ax.toExponential();
  let ePos = -1;
  for (let k = 0; k < es.length; k++) {
    if (es[k] === 'e') { ePos = k; break; }
  }
  const mantissa = es.slice(0, ePos);
  const exp = Number(es.slice(ePos + 1)); // value = D[0].D[1:] x 10^exp
  let digits = '';
  for (let k = 0; k < mantissa.length; k++) {
    if (mantissa[k] !== '.') digits += mantissa[k];
  }

  let out;
  if (exp >= -4 && exp <= 15) {
    // fixed notation: 1e-4 <= |x| < 1e16
    if (exp >= 0) {
      if (digits.length <= exp + 1) {
        out = digits;
        for (let k = digits.length; k < exp + 1; k++) out += '0';
        out += '.0';
      } else {
        out = digits.slice(0, exp + 1) + '.' + digits.slice(exp + 1);
      }
    } else {
      out = '0.';
      for (let k = 0; k < -exp - 1; k++) out += '0';
      out += digits;
    }
  } else {
    // exponential notation; mantissa always carries a dot ('.0' insertion rule)
    let m = digits[0] + '.';
    m += digits.length > 1 ? digits.slice(1) : '0';
    const ae = Math.abs(exp);
    out = m + 'e' + (exp < 0 ? '-' : '+') + (ae < 10 ? '0' + ae : String(ae));
  }
  return neg ? '-' + out : out;
}

// ---------------------------------------------------------------------------
// PyYAML double-quoted escape table (emitted body, no surrounding quotes).
// Output is pure ASCII. Iterates by code point so astral characters become
// a single \UXXXXXXXX escape.

function hexEscape(prefix, cp, width) {
  let h = cp.toString(16).toUpperCase();
  while (h.length < width) h = '0' + h;
  return prefix + h;
}

export function escapeDoubleQuoted(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    switch (cp) {
      case 0x22: out += '\\"'; continue;
      case 0x5C: out += '\\\\'; continue;
      case 0x00: out += '\\0'; continue;
      case 0x07: out += '\\a'; continue;
      case 0x08: out += '\\b'; continue;
      case 0x09: out += '\\t'; continue;
      case 0x0A: out += '\\n'; continue;
      case 0x0B: out += '\\v'; continue;
      case 0x0C: out += '\\f'; continue;
      case 0x0D: out += '\\r'; continue;
      case 0x1B: out += '\\e'; continue;
      case 0x85: out += '\\N'; continue;
      case 0xA0: out += '\\_'; continue;
      case 0x2028: out += '\\L'; continue;
      case 0x2029: out += '\\P'; continue;
      default: break;
    }
    if (cp >= 0x20 && cp <= 0x7E) {
      out += ch;
    } else if (cp <= 0xFF) {
      out += hexEscape('\\x', cp, 2);
    } else if (cp <= 0xFFFF) {
      out += hexEscape('\\u', cp, 4);
    } else {
      out += hexEscape('\\U', cp, 8);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// PyYAML timestamp dump form.

export function formatTimestamp(t) {
  let s = padLeft(t.year, 4) + '-' + padLeft(t.month, 2) + '-' + padLeft(t.day, 2);
  if (t.dateOnly) return s;
  s += ' ' + padLeft(t.hour, 2) + ':' + padLeft(t.minute, 2) + ':' + padLeft(t.second, 2);
  if (t.microsecond !== 0) s += '.' + padLeft(t.microsecond, 6);
  if (t.offsetMin !== null && t.offsetMin !== undefined) {
    const a = Math.abs(t.offsetMin);
    s += (t.offsetMin < 0 ? '-' : '+') + padLeft(Math.floor(a / 60), 2) + ':' + padLeft(a % 60, 2);
  }
  return s;
}

