import { execFileSync } from 'node:child_process';
import { pyFloatRepr } from '/output/lib/resolve.mjs';

const EXE = '/workspace/dataset/test13_executable';

// deterministic PRNG
let state = 0x12345678n;
function nextBits() {
  state = (state * 6364136223846793005n + 1442695040888963407n) & 0xFFFFFFFFFFFFFFFFn;
  state ^= state >> 29n;
  return state;
}

const buf = new ArrayBuffer(8);
const u8 = new Uint8Array(buf);
const f64 = new Float64Array(buf);

function randomDouble() {
  const bits = nextBits();
  for (let i = 0; i < 8; i++) u8[i] = Number((bits >> BigInt(i * 8)) & 0xFFn);
  return f64[0];
}

const specials = [
  0, -0, 1, -1, 0.5, -0.5, 0.1, 1e15, 1e16, 1e-4, 1e-5, 9007199254740992,
  123456789012345678.9, Number.MIN_VALUE, Number.MAX_VALUE, 4.9e-324,
  999999999999999.9, 1.5e300, -2.5e-5, 123456789.123456789, Math.PI, 1 / 3,
  1e21, 1e22, 123456789012345680000, 0.30000000000000004, 2 ** 53, 2 ** 53 + 2,
  1e-310, 2.2250738585072014e-308, 5e-324 * 3,
];

let pass = 0, fail = 0, skipped = 0;
const total = 600;
for (let t = 0; t < total + specials.length; t++) {
  const x = t < specials.length ? specials[t] : randomDouble();
  if (Number.isNaN(x) || !Number.isFinite(x)) { skipped++; continue; }
  // feed the double to the executable via an explicit !!float tag
  const js = x.toString();
  let input;
  if (js.indexOf('e') >= 0 || js.indexOf('E') >= 0) {
    input = '!!float "' + js + '"';
  } else {
    input = '!!float "' + js + '"';
  }
  let expected;
  try {
    expected = execFileSync(EXE, ['--a=' + input], { encoding: 'utf8' });
  } catch (e) {
    skipped++;
    continue;
  }
  const expBody = expected.trim(); // !!float "...."
  const mine = '!!float "' + pyFloatRepr(x) + '"';
  if (mine === expBody) pass++;
  else {
    fail++;
    console.log('DIFF x=' + js + '  exe=' + expBody + '  mine=' + mine);
  }
}
console.log('float fuzz: pass=' + pass + ' fail=' + fail + ' skipped=' + skipped);

